AssistantMessageToolRequest(name='create', tool_call_id='function-call-004c7e60-5493-460d-8a82-c2d10f1e3ed6', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    // Cart functionality
    const cartCountElement = document.getElementById('cart-count');
    const addToCartButtons = document.querySelectorAll('.add-to-cart');

    let cartCount = 0;

    addToCartButtons.forEach(button => {
        button.addEventListener('click', function() {
            // Increment cart count
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Visual feedback
            const originalText = this.textContent;
            this.textContent = 'Added!';
            this.style.backgroundColor = 'var(--text-primary)';
            this.style.color = 'var(--bg-base)';

            // Revert after 1.5s
            setTimeout(() => {
                this.textContent = originalText;
                this.style.backgroundColor = 'transparent';
                this.style.color = 'var(--text-primary)';
            }, 1500);
        });
    });

    // Newsletter submission
    const newsletterForm = document.getElementById('newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', function(e) {
            e.preventDefault();
            const input = this.querySelector('input[type="email"]');

            if (input.value) {
                const btn = this.querySelector('button');
                const originalContent = btn.innerHTML;

                btn.innerHTML = '✓';
                input.value = '';
                input.placeholder = 'Thanks for subscribing!';

                setTimeout(() => {
                    btn.innerHTML = originalContent;
                    input.placeholder = 'Email address';
                }, 3000);
            }
        });
    }

    // Smooth scrolling for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            const targetId = this.getAttribute('href');

            if (targetId === '#') return;

            const targetElement = document.querySelector(targetId);

            if (targetElement) {
                e.preventDefault();

                // Account for fixed header
                const headerOffset = 70;
                const elementPosition = targetElement.getBoundingClientRect().top;
                const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

                window.scrollTo({
                    top: offsetPosition,
                    behavior: 'smooth'
                });
            }
        });
    });
