    align-items: center;
    justify-content: center;
    padding: 0 4px;
}

/* Hero Section */
.hero {
    min-height: 80vh;
    display: flex;
    align-items: center;
    background: linear-gradient(to bottom, transparent, var(--bg-base)),
                radial-gradient(circle at top right, rgba(99, 102, 241, 0.15), transparent 40%),
                radial-gradient(circle at bottom left, rgba(20, 20, 20, 1), #0a0a0a);
    padding: 0 24px;
    position: relative;
    overflow: hidden;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.hero h1 {
    font-size: 4rem;
    margin-bottom: 16px;
    background: linear-gradient(to right, #fff, #a3a3a3);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero p {
    font-size: 1.125rem;
    color: var(--text-secondary);
    margin-bottom: 32px;
}

/* Sections */
.section {
    padding: 80px 24px;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 40px;
}

.section-header h2 {
    font-size: 2rem;
}

.section-desc {
    color: var(--text-secondary);
    margin-top: 8px;
}

.view-all {
    font-size: 0.95rem;
    color: var(--text-secondary);
    border-bottom: 1px solid transparent;
}

.view-all:hover {
    color: var(--text-primary);
    border-bottom-color: var(--text-primary);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 32px;
}

.product-card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-4px);
    border-color: #3f3f46;
    box-shadow: 0 12px 24px rgba(0,0,0,0.5);
}

.img-placeholder {
    width: 100%;
    aspect-ratio: 4/5;
    background-color: #2a2a2a;
}

.product-info {
    padding: 20px;
}

.product-title {
    font-size: 1.1rem;
    margin-bottom: 4px;
}

.product-category {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 16px;
}

.product-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.product-price {
    font-weight: 600;
    font-size: 1.1rem;
}

.add-to-cart {
    background: transparent;
    color: var(--text-primary);
    border: 1px solid var(--border);
    padding: 8px 16px;
    border-radius: var(--radius-sm);
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--text-primary);
    color: var(--bg-base);
}

/* Deals Section */
.deals-section {
    background: linear-gradient(45deg, #1e1b4b, #0f172a);
    padding: 80px 24px;
    text-align: center;
    border-top: 1px solid rgba(255,255,255,0.05);
    border-bottom: 1px solid rgba(255,255,255,0.05);
}

.deals-content {
    max-width: 600px;
    margin: 0 auto;
}

.deal-tag {
    display: inline-block;
    background: rgba(99, 102, 241, 0.2);
    color: #818cf8;
    padding: 4px 12px;
    border-radius: 100px;
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 16px;
}

.deals-section h2 {
    font-size: 2.5rem;
    margin-bottom: 16px;
}

.deals-section p {
    color: #94a3b8;
    margin-bottom: 32px;
    font-size: 1.1rem;
}

.deals-actions {
    display: flex;
    gap: 16px;
    justify-content: center;
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 32px;
}

.editorial-card {
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
    background-color: var(--bg-surface);
    transition: var(--transition);
}

.editorial-card:hover {
    border-color: #3f3f46;
}

.editorial-img {
    height: 300px;
    padding: 24px;
    display: flex;
    align-items: flex-end;
}

.editorial-category {
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(4px);
    padding: 4px 12px;
    border-radius: 100px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.editorial-info {
    padding: 24px;
}

.editorial-info h3 {
    font-size: 1.25rem;
    margin-bottom: 12px;
}

.editorial-info p {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 20px;
}

.read-more {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-weight: 500;
    font-size: 0.95rem;
    color: var(--text-primary);
}

.read-more svg {
    transition: transform 0.2s;
}

.read-more:hover svg {
    transform: translateX(4px);
}

/* Footer */
.footer {
    border-top: 1px solid var(--border);
    padding: 80px 0 32px;
    margin-top: 40px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 48px;
    margin-bottom: 64px;
}

.footer-logo {
    font-size: 1.5rem;
    margin-bottom: 16px;
}

.footer-brand-section p {
    color: var(--text-secondary);
    max-width: 250px;
}

.footer-links-group h4,
.footer-newsletter h4 {
    font-size: 1rem;
    margin-bottom: 20px;
}

.footer-links-group a {
    display: block;
    color: var(--text-secondary);
    margin-bottom: 12px;
    font-size: 0.95rem;
}

.footer-links-group a:hover {
    color: var(--text-primary);
}

.footer-newsletter p {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 16px;
}

.subscribe-form {
    display: flex;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    overflow: hidden;
}

.subscribe-form input {
    flex: 1;
    background: transparent;
    border: none;
    padding: 12px 16px;
    color: var(--text-primary);
    outline: none;
}

.subscribe-form input::placeholder {
    color: #52525b;
}

.subscribe-form button {
    background: var(--text-primary);
    color: var(--bg-base);
    border: none;
    padding: 0 20px;
    cursor: pointer;
    font-weight: bold;
    transition: var(--transition);
}

.subscribe-form button:hover {
    background: #d4d4d4;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 32px;
    border-top: 1px solid var(--border);
    color: var(--text-secondary);
    font-size: 0.85rem;
}

.social-links {
    display: flex;
    gap: 16px;
}

.social-links a:hover {
    color: var(--text-primary);
}

/* Responsive */
@media (max-width: 900px) {
